"""dialogues roster x new characters (277 clips). Written by the voice director (content), source AssetGen/audio/script/wave_*.txt -> voice_script.json; voice = char_id (VOIX_ARCHITECTURE.md principle 2). Never edit: new content goes to a new batch."""
ITEMS = [
    {'cat': 'dialogue', 'text': 'Votre cognac, mon colonel. Le troisième.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0061_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0061', 'turn': 1, 'speaker': 'A', 'context': 'cognac'},
    {'cat': 'dialogue', 'text': 'Le deuxième, Barnabé. Je compte mieux que vous.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0061_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0061', 'turn': 2, 'speaker': 'B', 'context': 'cognac'},
    {'cat': 'dialogue', 'text': 'Monsieur compte surtout plus lentement.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0061_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0061', 'turn': 3, 'speaker': 'A', 'context': 'cognac'},
    {'cat': 'dialogue', 'text': "Barnabé, vous fermerez mes volets avant l'aube.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0062_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0062', 'turn': 1, 'speaker': 'A', 'context': 'shutters'},
    {'cat': 'dialogue', 'text': "Ils le seront, monsieur le comte. Doublement. Et j'ai retiré le miroir.", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0062_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0062', 'turn': 2, 'speaker': 'B', 'context': 'shutters'},
    {'cat': 'dialogue', 'text': 'Vous êtes un trésor.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0062_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0062', 'turn': 3, 'speaker': 'A', 'context': 'shutters'},
    {'cat': 'dialogue', 'text': 'Barnabé, vous savez tout. Qui a pris le collier ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0063_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0063', 'turn': 1, 'speaker': 'A', 'context': 'secret'},
    {'cat': 'dialogue', 'text': "Je sais tout, mademoiselle. C'est pourquoi je ne dis rien.", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0063_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0063', 'turn': 2, 'speaker': 'B', 'context': 'secret'},
    {'cat': 'dialogue', 'text': 'Monsieur Victor, le tailleur a téléphoné. Avant que la ligne ne soit coupée.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0064_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0064', 'turn': 1, 'speaker': 'A', 'context': 'bill'},
    {'cat': 'dialogue', 'text': 'Et que voulait-il ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0064_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0064', 'turn': 2, 'speaker': 'B', 'context': 'bill'},
    {'cat': 'dialogue', 'text': 'Sa queue-de-pie, monsieur. Celle que vous portez.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0064_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0064', 'turn': 3, 'speaker': 'A', 'context': 'bill'},
    {'cat': 'dialogue', 'text': "Vous regardez souvent l'horloge, Barnabé.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0065_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0065', 'turn': 1, 'speaker': 'A', 'context': 'clock'},
    {'cat': 'dialogue', 'text': "C'est mon métier de savoir l'heure, monsieur.", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0065_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0065', 'turn': 2, 'speaker': 'B', 'context': 'clock'},
    {'cat': 'dialogue', 'text': "Et c'est le mien de savoir pourquoi.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0065_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0065', 'turn': 3, 'speaker': 'A', 'context': 'clock'},
    {'cat': 'dialogue', 'text': 'Barnabé, mon chou, tu me trouves un pianiste pour minuit ?', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0066_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0066', 'turn': 1, 'speaker': 'A', 'context': 'rehearsal'},
    {'cat': 'dialogue', 'text': 'Le pianiste est ivre, mademoiselle. Je peux vous trouver le piano.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0066_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0066', 'turn': 2, 'speaker': 'B', 'context': 'rehearsal'},
    {'cat': 'dialogue', 'text': 'Colonel, avez-vous déjà chassé le tigre ?', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0067_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0067', 'turn': 1, 'speaker': 'A', 'context': 'tiger'},
    {'cat': 'dialogue', 'text': "Jamais. Mais j'ai chassé le Prussien, c'est plus grand.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0067_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0067', 'turn': 2, 'speaker': 'B', 'context': 'tiger'},
    {'cat': 'dialogue', 'text': 'Et plus rayé, je suppose.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0067_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0067', 'turn': 3, 'speaker': 'A', 'context': 'tiger'},
    {'cat': 'dialogue', 'text': 'Votre palais a combien de pièces, prince ?', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0068_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0068', 'turn': 1, 'speaker': 'A', 'context': 'palaces'},
    {'cat': 'dialogue', 'text': 'Trois cent douze. Et le vôtre, comte ?', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0068_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0068', 'turn': 2, 'speaker': 'B', 'context': 'palaces'},
    {'cat': 'dialogue', 'text': 'Une seule compte vraiment. La crypte.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0068_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0068', 'turn': 3, 'speaker': 'A', 'context': 'palaces'},
    {'cat': 'dialogue', 'text': 'Mademoiselle, cette émeraude vous va presque aussi bien que mon turban.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0069_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0069', 'turn': 1, 'speaker': 'A', 'context': 'emerald'},
    {'cat': 'dialogue', 'text': 'Presque ? Vous êtes bien sûr de vous, prince.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0069_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0069', 'turn': 2, 'speaker': 'B', 'context': 'emerald'},
    {'cat': 'dialogue', 'text': "Je suis prince. C'est un peu mon métier.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0069_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0069', 'turn': 3, 'speaker': 'A', 'context': 'emerald'},
    {'cat': 'dialogue', 'text': 'Prince, entre gentlemen, vous ne prêteriez pas quelques roupies ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'gossip', 'line_id': 'CD0070_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0070', 'turn': 1, 'speaker': 'A', 'context': 'loan'},
    {'cat': 'dialogue', 'text': 'Combien de roupies, mon ami ?', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0070_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0070', 'turn': 2, 'speaker': 'B', 'context': 'loan'},
    {'cat': 'dialogue', 'text': 'Disons un éléphant.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'gossip', 'line_id': 'CD0070_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0070', 'turn': 3, 'speaker': 'A', 'context': 'loan'},
    {'cat': 'dialogue', 'text': "Mon astrologue m'avait parlé d'un homme masqué qui veillerait cette nuit.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0071_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0071', 'turn': 1, 'speaker': 'A', 'context': 'stars'},
    {'cat': 'dialogue', 'text': 'Votre astrologue est bien informé.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0071_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0071', 'turn': 2, 'speaker': 'B', 'context': 'stars'},
    {'cat': 'dialogue', 'text': 'Il est surtout bien payé.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0071_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0071', 'turn': 3, 'speaker': 'A', 'context': 'stars'},
    {'cat': 'dialogue', 'text': 'Dis donc, prince, tu danses la java ?', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0072_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0072', 'turn': 1, 'speaker': 'A', 'context': 'dance'},
    {'cat': 'dialogue', 'text': 'Je danse tout, mademoiselle. Même ce que je ne connais pas.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0072_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0072', 'turn': 2, 'speaker': 'B', 'context': 'dance'},
    {'cat': 'dialogue', 'text': 'Alors viens, je te montre. Et tu me marches pas dessus.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0072_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0072', 'turn': 3, 'speaker': 'A', 'context': 'dance'},
    {'cat': 'dialogue', 'text': 'Votre trompette réveillerait un régiment entier !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0073_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0073', 'turn': 1, 'speaker': 'A', 'context': 'clarion'},
    {'cat': 'dialogue', 'text': "Merci, colonel ! C'était le but, mon pote.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0073_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0073', 'turn': 2, 'speaker': 'B', 'context': 'clarion'},
    {'cat': 'dialogue', 'text': 'Je ne suis pas votre pote.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0073_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0073', 'turn': 3, 'speaker': 'A', 'context': 'clarion'},
    {'cat': 'dialogue', 'text': 'Pas encore. Attends le prochain morceau.', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0073_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0073', 'turn': 4, 'speaker': 'B', 'context': 'clarion'},
    {'cat': 'dialogue', 'text': "Hé, comte ! Vous restez jusqu'au dernier morceau ?", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0074_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0074', 'turn': 1, 'speaker': 'A', 'context': 'night owl'},
    {'cat': 'dialogue', 'text': "Je reste toujours jusqu'au bout, monsieur Sonny. C'est le jour qui me chasse.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0074_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0074', 'turn': 2, 'speaker': 'B', 'context': 'night owl'},
    {'cat': 'dialogue', 'text': 'Un vrai musicien, alors !', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0074_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0074', 'turn': 3, 'speaker': 'A', 'context': 'night owl'},
    {'cat': 'dialogue', 'text': "Sonny, vous jouez un slow ? J'ai un cavalier à éblouir.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0075_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0075', 'turn': 1, 'speaker': 'A', 'context': 'slow'},
    {'cat': 'dialogue', 'text': 'Pour toi, ma belle, je joue même un slow sur un tambour.', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0075_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0075', 'turn': 2, 'speaker': 'B', 'context': 'slow'},
    {'cat': 'dialogue', 'text': 'Victor, mon pote ! Tu me dois encore la tournée de Montmartre.', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0076_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0076', 'turn': 1, 'speaker': 'A', 'context': 'bet'},
    {'cat': 'dialogue', 'text': 'Je vous la paie au prochain bal, promis.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0076_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0076', 'turn': 2, 'speaker': 'B', 'context': 'bet'},
    {'cat': 'dialogue', 'text': "C'est ce que tu as dit au dernier, man.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0076_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0076', 'turn': 3, 'speaker': 'A', 'context': 'bet'},
    {'cat': 'dialogue', 'text': 'Votre musique couvre beaucoup de bruits, ce soir.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0077_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0077', 'turn': 1, 'speaker': 'A', 'context': 'quiet'},
    {'cat': 'dialogue', 'text': "C'est le jazz, mon pote. Ça couvre tout, même les secrets.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0077_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0077', 'turn': 2, 'speaker': 'B', 'context': 'quiet'},
    {'cat': 'dialogue', 'text': "C'est bien ce qui m'inquiète.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0077_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0077', 'turn': 3, 'speaker': 'A', 'context': 'quiet'},
    {'cat': 'dialogue', 'text': 'Odette, ma belle ! On fait le duo de minuit ?', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0078_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0078', 'turn': 1, 'speaker': 'A', 'context': 'duet'},
    {'cat': 'dialogue', 'text': 'Si ton trompettiste dessoûle, mon chou.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0078_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0078', 'turn': 2, 'speaker': 'B', 'context': 'duet'},
    {'cat': 'dialogue', 'text': 'Il dessoûle jamais. Il joue mieux comme ça.', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0078_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0078', 'turn': 3, 'speaker': 'A', 'context': 'duet'},
    {'cat': 'dialogue', 'text': 'Colonel ! Vous avez servi en Égypte, je crois ?', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0079_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0079', 'turn': 1, 'speaker': 'A', 'context': 'egypt'},
    {'cat': 'dialogue', 'text': 'Deux ans. Du sable, des mouches et pas un cognac.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0079_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0079', 'turn': 2, 'speaker': 'B', 'context': 'egypt'},
    {'cat': 'dialogue', 'text': 'Mais les tombeaux, colonel, les tombeaux !', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0079_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0079', 'turn': 3, 'speaker': 'A', 'context': 'egypt'},
    {'cat': 'dialogue', 'text': "J'en ai rempli quelques-uns, professeur. Pas visités.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0079_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0079', 'turn': 4, 'speaker': 'B', 'context': 'egypt'},
    {'cat': 'dialogue', 'text': 'Comte, votre bague... ce motif date du quinzième siècle !', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0080_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0080', 'turn': 1, 'speaker': 'A', 'context': 'age'},
    {'cat': 'dialogue', 'text': "Vous avez l'œil, professeur.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0080_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0080', 'turn': 2, 'speaker': 'B', 'context': 'age'},
    {'cat': 'dialogue', 'text': "Où l'avez-vous achetée ?", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0080_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0080', 'turn': 3, 'speaker': 'A', 'context': 'age'},
    {'cat': 'dialogue', 'text': "Je ne l'ai pas achetée. Je l'ai portée dès le début.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0080_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0080', 'turn': 4, 'speaker': 'B', 'context': 'age'},
    {'cat': 'dialogue', 'text': "Professeur, c'est vrai que vous avez dormi dans une pyramide ?", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0081_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0081', 'turn': 1, 'speaker': 'A', 'context': 'mummy'},
    {'cat': 'dialogue', 'text': 'Trois nuits ! Avec une momie. Elle ronflait moins que mon assistant.', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0081_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0081', 'turn': 2, 'speaker': 'B', 'context': 'mummy'},
    {'cat': 'dialogue', 'text': 'Jeune homme, savez-vous lire les hiéroglyphes ?', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0082_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0082', 'turn': 1, 'speaker': 'A', 'context': 'treasure'},
    {'cat': 'dialogue', 'text': 'Non, mais je sais lire les cartes à jouer.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0082_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0082', 'turn': 2, 'speaker': 'B', 'context': 'treasure'},
    {'cat': 'dialogue', 'text': "Hm. C'est presque aussi ancien. Et aussi maudit.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0082_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0082', 'turn': 3, 'speaker': 'A', 'context': 'treasure'},
    {'cat': 'dialogue', 'text': "Professeur. Vous êtes monté au grenier tout à l'heure.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0083_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0083', 'turn': 1, 'speaker': 'A', 'context': 'attic'},
    {'cat': 'dialogue', 'text': 'Ah ? Oui ! Enfin, je crois. Où en étais-je ?', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0083_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0083', 'turn': 2, 'speaker': 'B', 'context': 'attic'},
    {'cat': 'dialogue', 'text': 'Au grenier.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0083_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0083', 'turn': 3, 'speaker': 'A', 'context': 'attic'},
    {'cat': 'dialogue', 'text': "Ah oui ! Il y a une caisse marquée « Ne pas ouvrir ». Je l'ai ouverte.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0083_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0083', 'turn': 4, 'speaker': 'B', 'context': 'attic'},
    {'cat': 'dialogue', 'text': 'Dis donc, professeur, Cléopâtre, elle chantait ?', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0084_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0084', 'turn': 1, 'speaker': 'A', 'context': 'cleopatra'},
    {'cat': 'dialogue', 'text': 'Probablement, mademoiselle ! Mais pas aussi bien que vous.', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0084_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0084', 'turn': 2, 'speaker': 'B', 'context': 'cleopatra'},
    {'cat': 'dialogue', 'text': "T'es un charmeur, toi, sous ta poussière.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0084_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0084', 'turn': 3, 'speaker': 'A', 'context': 'cleopatra'},
    {'cat': 'dialogue', 'text': 'Chauffeur ! Tenez-vous droit !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0085_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0085', 'turn': 1, 'speaker': 'A', 'context': 'posture'},
    {'cat': 'dialogue', 'text': 'Oui, mon colonel ! Pardon, mon colonel !', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0085_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0085', 'turn': 2, 'speaker': 'B', 'context': 'posture'},
    {'cat': 'dialogue', 'text': "Ah, ça, c'est un garçon bien élevé.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0085_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0085', 'turn': 3, 'speaker': 'A', 'context': 'posture'},
    {'cat': 'dialogue', 'text': 'Mon garçon, conduisez-vous de nuit ?', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0086_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0086', 'turn': 1, 'speaker': 'A', 'context': 'night drive'},
    {'cat': 'dialogue', 'text': 'Oui, monsieur le comte. Avec les phares.', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0086_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0086', 'turn': 2, 'speaker': 'B', 'context': 'night drive'},
    {'cat': 'dialogue', 'text': 'Je préfère sans. On voit mieux les loups.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0086_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0086', 'turn': 3, 'speaker': 'A', 'context': 'night drive'},
    {'cat': 'dialogue', 'text': 'Pardon, mademoiselle. Votre voiture est rangée au sec.', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0087_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0087', 'turn': 1, 'speaker': 'A', 'context': 'car'},
    {'cat': 'dialogue', 'text': "Je n'ai pas de voiture, Lucien.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0087_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0087', 'turn': 2, 'speaker': 'B', 'context': 'car'},
    {'cat': 'dialogue', 'text': "Ah ? Alors j'ai rangé celle de quelqu'un d'autre.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0087_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0087', 'turn': 3, 'speaker': 'A', 'context': 'car'},
    {'cat': 'dialogue', 'text': "Lucien, vous me prêteriez la voiture de votre patron ? Juste pour l'aube.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'gossip', 'line_id': 'CD0088_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0088', 'turn': 1, 'speaker': 'A', 'context': 'borrow'},
    {'cat': 'dialogue', 'text': 'Je peux pas, monsieur Victor. Et puis, on est sur une île.', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0088_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0088', 'turn': 2, 'speaker': 'B', 'context': 'borrow'},
    {'cat': 'dialogue', 'text': 'Ah. Le détail qui tue.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'gossip', 'line_id': 'CD0088_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0088', 'turn': 3, 'speaker': 'A', 'context': 'borrow'},
    {'cat': 'dialogue', 'text': 'Lucien. Vous avez graissé les portes, ce soir.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0089_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0089', 'turn': 1, 'speaker': 'A', 'context': 'greased'},
    {'cat': 'dialogue', 'text': 'Oui, monsieur. Elles grinçaient.', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0089_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0089', 'turn': 2, 'speaker': 'B', 'context': 'greased'},
    {'cat': 'dialogue', 'text': "Maintenant, on n'entend plus qui entre. Ni qui sort.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0089_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0089', 'turn': 3, 'speaker': 'A', 'context': 'greased'},
    {'cat': 'dialogue', 'text': "Oh. J'avais pas pensé à ça.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0089_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0089', 'turn': 4, 'speaker': 'B', 'context': 'greased'},
    {'cat': 'dialogue', 'text': "T'es tout rouge, toi. Je te fais peur ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0090_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0090', 'turn': 1, 'speaker': 'A', 'context': 'shy'},
    {'cat': 'dialogue', 'text': 'Non, mademoiselle. Enfin, un peu. Je vous ai vue sur une affiche.', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0090_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0090', 'turn': 2, 'speaker': 'B', 'context': 'shy'},
    {'cat': 'dialogue', 'text': "Alors souris, t'es en face de l'affiche !", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0090_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0090', 'turn': 3, 'speaker': 'A', 'context': 'shy'},
    {'cat': 'dialogue', 'text': 'Belles médailles, colonel. Combien ça vaut, au poids ?', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0091_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0091', 'turn': 1, 'speaker': 'A', 'context': 'medals'},
    {'cat': 'dialogue', 'text': 'Plus que votre vie, monsieur !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0091_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0091', 'turn': 2, 'speaker': 'B', 'context': 'medals'},
    {'cat': 'dialogue', 'text': "Heh. C'est pas cher, alors.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0091_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0091', 'turn': 3, 'speaker': 'A', 'context': 'medals'},
    {'cat': 'dialogue', 'text': 'Vous ne retirez jamais vos gants, monsieur ?', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0092_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0092', 'turn': 1, 'speaker': 'A', 'context': 'gloves'},
    {'cat': 'dialogue', 'text': 'Jamais, comte. Et vous, vous sortez jamais de jour ?', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0092_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0092', 'turn': 2, 'speaker': 'B', 'context': 'gloves'},
    {'cat': 'dialogue', 'text': 'Nous avons chacun nos petites précautions.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0092_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0092', 'turn': 3, 'speaker': 'A', 'context': 'gloves'},
    {'cat': 'dialogue', 'text': 'Joli collier, mademoiselle. Ce serait dommage de le perdre.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0093_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0093', 'turn': 1, 'speaker': 'A', 'context': 'necklace'},
    {'cat': 'dialogue', 'text': "C'est une menace ou un compliment ?", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0093_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0093', 'turn': 2, 'speaker': 'B', 'context': 'necklace'},
    {'cat': 'dialogue', 'text': "Chez moi, c'est la même chose.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0093_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0093', 'turn': 3, 'speaker': 'A', 'context': 'necklace'},
    {'cat': 'dialogue', 'text': 'Victor ! Mon ami ! Tu as mes cinq mille dollars ?', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0094_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0094', 'turn': 1, 'speaker': 'A', 'context': 'debt'},
    {'cat': 'dialogue', 'text': 'Tony ! Quelle surprise ! Je les ai... presque.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0094_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0094', 'turn': 2, 'speaker': 'B', 'context': 'debt'},
    {'cat': 'dialogue', 'text': "Presque, c'est un mot que j'aime pas, Victor.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0094_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0094', 'turn': 3, 'speaker': 'A', 'context': 'debt'},
    {'cat': 'dialogue', 'text': "Alors disons bientôt. C'est plus joli.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0094_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0094', 'turn': 4, 'speaker': 'B', 'context': 'debt'},
    {'cat': 'dialogue', 'text': 'Je vous ai vu sortir du bureau, Tony.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0095_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0095', 'turn': 1, 'speaker': 'A', 'context': 'watched'},
    {'cat': 'dialogue', 'text': "Moi ? Tu te trompes, mon ami. J'étais aux toilettes. Avec des témoins.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0095_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0095', 'turn': 2, 'speaker': 'B', 'context': 'watched'},
    {'cat': 'dialogue', 'text': 'Des témoins aux toilettes ?', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0095_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0095', 'turn': 3, 'speaker': 'A', 'context': 'watched'},
    {'cat': 'dialogue', 'text': 'Je suis un homme prudent.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0095_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0095', 'turn': 4, 'speaker': 'B', 'context': 'watched'},
    {'cat': 'dialogue', 'text': "Odette, ma chérie. Ton patron du cabaret, il me doit de l'argent.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0096_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0096', 'turn': 1, 'speaker': 'A', 'context': 'cabaret'},
    {'cat': 'dialogue', 'text': 'Et alors ? Moi, je te dois rien, Tony.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0096_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0096', 'turn': 2, 'speaker': 'B', 'context': 'cabaret'},
    {'cat': 'dialogue', 'text': "C'est vrai. Alors on reste amis.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0096_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0096', 'turn': 3, 'speaker': 'A', 'context': 'cabaret'},
    {'cat': 'dialogue', 'text': "Colonel ! Au Texas, j'ai mille chevaux !", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0097_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0097', 'turn': 1, 'speaker': 'A', 'context': 'horses'},
    {'cat': 'dialogue', 'text': 'Et combien savez-vous monter ?', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0097_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0097', 'turn': 2, 'speaker': 'B', 'context': 'horses'},
    {'cat': 'dialogue', 'text': 'Ha ! Aucun ! Je les regarde depuis la Cadillac.', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0097_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0097', 'turn': 3, 'speaker': 'A', 'context': 'horses'},
    {'cat': 'dialogue', 'text': 'Monsieur Callahan, vous voulez acheter mon château, paraît-il ?', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0098_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0098', 'turn': 1, 'speaker': 'A', 'context': 'castle'},
    {'cat': 'dialogue', 'text': "Ha ! S'il est assez grand, oui !", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0098_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0098', 'turn': 2, 'speaker': 'B', 'context': 'castle'},
    {'cat': 'dialogue', 'text': 'Il est très grand. Mais les anciens propriétaires y habitent encore.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0098_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0098', 'turn': 3, 'speaker': 'A', 'context': 'castle'},
    {'cat': 'dialogue', 'text': 'Ils paient un loyer ?', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0098_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0098', 'turn': 4, 'speaker': 'B', 'context': 'castle'},
    {'cat': 'dialogue', 'text': 'Mademoiselle Sandra ! Au Texas, cette bague serait un caillou !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0099_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0099', 'turn': 1, 'speaker': 'A', 'context': 'ring'},
    {'cat': 'dialogue', 'text': "Alors offrez-m'en une texane, monsieur Callahan.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0099_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0099', 'turn': 2, 'speaker': 'B', 'context': 'ring'},
    {'cat': 'dialogue', 'text': 'Ha ! Elle ne tiendrait pas sur votre doigt !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0099_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0099', 'turn': 3, 'speaker': 'A', 'context': 'ring'},
    {'cat': 'dialogue', 'text': 'Monsieur Callahan, vous cherchez à investir ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0100_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0100', 'turn': 1, 'speaker': 'A', 'context': 'investor'},
    {'cat': 'dialogue', 'text': "Toujours, l'ami ! Dans quoi ?", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0100_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0100', 'turn': 2, 'speaker': 'B', 'context': 'investor'},
    {'cat': 'dialogue', 'text': 'Dans moi. Rendement garanti, ou presque.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0100_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0100', 'turn': 3, 'speaker': 'A', 'context': 'investor'},
    {'cat': 'dialogue', 'text': "Ha ha ha ! J'aime votre culot !", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0100_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0100', 'turn': 4, 'speaker': 'B', 'context': 'investor'},
    {'cat': 'dialogue', 'text': "Hé, l'ami masqué ! Vous parlez jamais ?", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0101_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0101', 'turn': 1, 'speaker': 'A', 'context': 'loud'},
    {'cat': 'dialogue', 'text': "Quand c'est nécessaire.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0101_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0101', 'turn': 2, 'speaker': 'B', 'context': 'loud'},
    {'cat': 'dialogue', 'text': "Au Texas, c'est nécessaire tout le temps !", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0101_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0101', 'turn': 3, 'speaker': 'A', 'context': 'loud'},
    {'cat': 'dialogue', 'text': 'Il est grand, ton chapeau, cow-boy !', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0102_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0102', 'turn': 1, 'speaker': 'A', 'context': 'hat'},
    {'cat': 'dialogue', 'text': "Dix gallons, ma petite dame ! Vous voulez l'essayer ?", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0102_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0102', 'turn': 2, 'speaker': 'B', 'context': 'hat'},
    {'cat': 'dialogue', 'text': 'Je risque de disparaître dedans.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0102_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0102', 'turn': 3, 'speaker': 'A', 'context': 'hat'},
    {'cat': 'dialogue', 'text': 'Colonel. Sur mer, un capitaine passe avant un colonel.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0103_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0103', 'turn': 1, 'speaker': 'A', 'context': 'ranks'},
    {'cat': 'dialogue', 'text': 'Nous sommes à terre, capitaine.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0103_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0103', 'turn': 2, 'speaker': 'B', 'context': 'ranks'},
    {'cat': 'dialogue', 'text': 'Avec cette pluie ? Plus pour longtemps.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0103_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0103', 'turn': 3, 'speaker': 'A', 'context': 'ranks'},
    {'cat': 'dialogue', 'text': "Capitaine, j'ai traversé l'Atlantique avec vous, en dix-neuf.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0104_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0104', 'turn': 1, 'speaker': 'A', 'context': 'crossing'},
    {'cat': 'dialogue', 'text': 'Je ne me souviens pas de vous, monsieur le comte.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0104_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0104', 'turn': 2, 'speaker': 'B', 'context': 'crossing'},
    {'cat': 'dialogue', 'text': 'Je voyageais dans la soute. Avec ma terre natale.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0104_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0104', 'turn': 3, 'speaker': 'A', 'context': 'crossing'},
    {'cat': 'dialogue', 'text': 'Capitaine, cette tempête est dangereuse ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0105_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0105', 'turn': 1, 'speaker': 'A', 'context': 'storm'},
    {'cat': 'dialogue', 'text': 'Pour un bateau, oui. Pour un manoir, moins. Pour un cœur, ça dépend.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0105_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0105', 'turn': 2, 'speaker': 'B', 'context': 'storm'},
    {'cat': 'dialogue', 'text': 'Vous, je vous reconnais. Vous trichiez aux cartes sur mon paquebot.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0106_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0106', 'turn': 1, 'speaker': 'A', 'context': 'cards aboard'},
    {'cat': 'dialogue', 'text': "Moi ? J'avais de la chance, capitaine.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0106_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0106', 'turn': 2, 'speaker': 'B', 'context': 'cards aboard'},
    {'cat': 'dialogue', 'text': 'Sept fois de suite, avec quatre as ?', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0106_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0106', 'turn': 3, 'speaker': 'A', 'context': 'cards aboard'},
    {'cat': 'dialogue', 'text': "Capitaine. Le phare s'est éteint à onze heures dix.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0107_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0107', 'turn': 1, 'speaker': 'A', 'context': 'lighthouse'},
    {'cat': 'dialogue', 'text': "Je l'ai remarqué aussi. Un phare ne s'éteint pas tout seul.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0107_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0107', 'turn': 2, 'speaker': 'B', 'context': 'lighthouse'},
    {'cat': 'dialogue', 'text': 'Alors nous sommes deux à veiller.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0107_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0107', 'turn': 3, 'speaker': 'A', 'context': 'lighthouse'},
    {'cat': 'dialogue', 'text': 'Mademoiselle, je vous ai entendue chanter à Brest, pour mes marins.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0108_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0108', 'turn': 1, 'speaker': 'A', 'context': 'sailors'},
    {'cat': 'dialogue', 'text': 'Ah ! Tes marins, ils chantaient plus fort que moi !', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0108_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0108', 'turn': 2, 'speaker': 'B', 'context': 'sailors'},
    {'cat': 'dialogue', 'text': 'Et plus faux, je le crains.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0108_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0108', 'turn': 3, 'speaker': 'A', 'context': 'sailors'},
    {'cat': 'dialogue', 'text': "Colonel. Vous m'avez fait la cour en mille neuf cent deux.", 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0109_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0109', 'turn': 1, 'speaker': 'A', 'context': '1902'},
    {'cat': 'dialogue', 'text': "Et vous m'avez dit non, duchesse.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0109_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0109', 'turn': 2, 'speaker': 'B', 'context': '1902'},
    {'cat': 'dialogue', 'text': "J'ai bien fait. Regardez votre moustache.", 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0109_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0109', 'turn': 3, 'speaker': 'A', 'context': '1902'},
    {'cat': 'dialogue', 'text': "Duchesse, vous souvenez-vous des bals d'avant-guerre ?", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0110_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0110', 'turn': 1, 'speaker': 'A', 'context': 'old times'},
    {'cat': 'dialogue', 'text': 'Évidemment. Et vous, comte, de quelle guerre parlez-vous ?', 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0110_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0110', 'turn': 2, 'speaker': 'B', 'context': 'old times'},
    {'cat': 'dialogue', 'text': 'Ah. Il y en a eu tant.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0110_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0110', 'turn': 3, 'speaker': 'A', 'context': 'old times'},
    {'cat': 'dialogue', 'text': 'Mademoiselle, combien de fiancés, cette année ?', 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0111_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0111', 'turn': 1, 'speaker': 'A', 'context': 'fiances'},
    {'cat': 'dialogue', 'text': 'Trois, duchesse.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0111_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0111', 'turn': 2, 'speaker': 'B', 'context': 'fiances'},
    {'cat': 'dialogue', 'text': "À votre âge, j'en avais sept. Et je les ai tous refusés.", 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0111_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0111', 'turn': 3, 'speaker': 'A', 'context': 'fiances'},
    {'cat': 'dialogue', 'text': 'Duchesse, vous êtes resplendissante.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0112_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0112', 'turn': 1, 'speaker': 'A', 'context': 'flattery'},
    {'cat': 'dialogue', 'text': 'Je sais, jeune homme. Combien voulez-vous ?', 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0112_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0112', 'turn': 2, 'speaker': 'B', 'context': 'flattery'},
    {'cat': 'dialogue', 'text': 'Vous, le masqué ! Retirez ce masque, on ne parle pas à une duchesse caché.', 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0113_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0113', 'turn': 1, 'speaker': 'A', 'context': 'manners'},
    {'cat': 'dialogue', 'text': 'Tout le monde est masqué, duchesse. Vous aussi.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0113_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0113', 'turn': 2, 'speaker': 'B', 'context': 'manners'},
    {'cat': 'dialogue', 'text': "Moi, c'est différent. Je suis une duchesse.", 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0113_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0113', 'turn': 3, 'speaker': 'A', 'context': 'manners'},
    {'cat': 'dialogue', 'text': "Bonsoir, duchesse ! Vous venez m'écouter au cabaret, un de ces soirs ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0114_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0114', 'turn': 1, 'speaker': 'A', 'context': 'cabaret'},
    {'cat': 'dialogue', 'text': "Au cabaret ? Voyons ! Je n'y vais que déguisée.", 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0114_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0114', 'turn': 2, 'speaker': 'B', 'context': 'cabaret'},
    {'cat': 'dialogue', 'text': "Ce soir, vous êtes masquée. C'est le moment !", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0114_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0114', 'turn': 3, 'speaker': 'A', 'context': 'cabaret'},
    {'cat': 'dialogue', 'text': 'Oh, colonel ! Vous êtes un vrai héros de guerre ?', 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0115_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0115', 'turn': 1, 'speaker': 'A', 'context': 'war hero'},
    {'cat': 'dialogue', 'text': 'Un vrai, mademoiselle. Avec de vraies médailles.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0115_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0115', 'turn': 2, 'speaker': 'B', 'context': 'war hero'},
    {'cat': 'dialogue', 'text': 'Darling, vous seriez parfait dans mon prochain film !', 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0115_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0115', 'turn': 3, 'speaker': 'A', 'context': 'war hero'},
    {'cat': 'dialogue', 'text': "Mademoiselle, vous avez le cou le plus photogénique d'Europe.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0116_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0116', 'turn': 1, 'speaker': 'A', 'context': 'neck'},
    {'cat': 'dialogue', 'text': 'Oh darling ! Vous voulez une photo ?', 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0116_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0116', 'turn': 2, 'speaker': 'B', 'context': 'neck'},
    {'cat': 'dialogue', 'text': 'Je ne vais pas très bien sur les photos.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0116_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0116', 'turn': 3, 'speaker': 'A', 'context': 'neck'},
    {'cat': 'dialogue', 'text': 'Oh, votre robe ! Elle est jolie. Pour une robe française.', 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0117_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0117', 'turn': 1, 'speaker': 'A', 'context': 'rivals'},
    {'cat': 'dialogue', 'text': 'Et la vôtre est très... hollywoodienne. Courageuse.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0117_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0117', 'turn': 2, 'speaker': 'B', 'context': 'rivals'},
    {'cat': 'dialogue', 'text': 'Merci, darling ! Je crois.', 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0117_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0117', 'turn': 3, 'speaker': 'A', 'context': 'rivals'},
    {'cat': 'dialogue', 'text': 'Mademoiselle Vivienne, êtes-vous une héritière ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0118_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0118', 'turn': 1, 'speaker': 'A', 'context': 'heiress'},
    {'cat': 'dialogue', 'text': 'Oh non, darling, je travaille ! Six films !', 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0118_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0118', 'turn': 2, 'speaker': 'B', 'context': 'heiress'},
    {'cat': 'dialogue', 'text': 'Ah. Quel dommage. Enfin, vous êtes charmante quand même.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0118_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0118', 'turn': 3, 'speaker': 'A', 'context': 'heiress'},
    {'cat': 'dialogue', 'text': 'Oh ! Vous êtes si mystérieux ! Vous êtes acteur ?', 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0119_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0119', 'turn': 1, 'speaker': 'A', 'context': 'mysterious'},
    {'cat': 'dialogue', 'text': 'Non.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0119_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0119', 'turn': 2, 'speaker': 'B', 'context': 'mysterious'},
    {'cat': 'dialogue', 'text': 'Vous devriez. Personne ne parle aussi peu à Hollywood.', 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0119_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0119', 'turn': 3, 'speaker': 'A', 'context': 'mysterious'},
    {'cat': 'dialogue', 'text': "Alors, la star, ça fait quoi d'être sur les affiches ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0120_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0120', 'turn': 1, 'speaker': 'A', 'context': 'stars'},
    {'cat': 'dialogue', 'text': 'Oh darling, ça fait mal au cou. Il faut toujours lever le menton !', 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0120_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0120', 'turn': 2, 'speaker': 'B', 'context': 'stars'},
    {'cat': 'dialogue', 'text': "Moi, sur mes affiches, je lève la jambe. C'est plus fatigant.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0120_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0120', 'turn': 3, 'speaker': 'A', 'context': 'stars'},
    {'cat': 'dialogue', 'text': 'Colonel, vous êtes marié ?', 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0121_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0121', 'turn': 1, 'speaker': 'A', 'context': 'widow'},
    {'cat': 'dialogue', 'text': 'Oui, madame. Pourquoi ?', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0121_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0121', 'turn': 2, 'speaker': 'B', 'context': 'widow'},
    {'cat': 'dialogue', 'text': 'Pour rien. Je me renseigne toujours.', 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0121_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0121', 'turn': 3, 'speaker': 'A', 'context': 'widow'},
    {'cat': 'dialogue', 'text': 'Madame, le noir vous va à merveille.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0122_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0122', 'turn': 1, 'speaker': 'A', 'context': 'kindred'},
    {'cat': 'dialogue', 'text': 'Et la nuit vous va bien, comte.', 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0122_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0122', 'turn': 2, 'speaker': 'B', 'context': 'kindred'},
    {'cat': 'dialogue', 'text': 'Nous devrions nous voir plus souvent. Après le coucher du soleil.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0122_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0122', 'turn': 3, 'speaker': 'A', 'context': 'kindred'},
    {'cat': 'dialogue', 'text': "Avec plaisir. Je n'ai plus de mari à prévenir.", 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0122_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0122', 'turn': 4, 'speaker': 'B', 'context': 'kindred'},
    {'cat': 'dialogue', 'text': 'Ophélie, ma chère, combien de maris, déjà ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0123_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0123', 'turn': 1, 'speaker': 'A', 'context': 'husbands'},
    {'cat': 'dialogue', 'text': 'Trois. Comme vos fiançailles.', 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0123_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0123', 'turn': 2, 'speaker': 'B', 'context': 'husbands'},
    {'cat': 'dialogue', 'text': 'Moi, au moins, les miens sont vivants.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0123_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0123', 'turn': 3, 'speaker': 'A', 'context': 'husbands'},
    {'cat': 'dialogue', 'text': "Pour l'instant.", 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0123_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0123', 'turn': 4, 'speaker': 'B', 'context': 'husbands'},
    {'cat': 'dialogue', 'text': 'Monsieur Victor, vous cherchez une héritière, paraît-il.', 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0124_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0124', 'turn': 1, 'speaker': 'A', 'context': 'proposal'},
    {'cat': 'dialogue', 'text': 'Vous êtes riche, madame ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0124_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0124', 'turn': 2, 'speaker': 'B', 'context': 'proposal'},
    {'cat': 'dialogue', 'text': "Très. J'hérite souvent.", 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0124_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0124', 'turn': 3, 'speaker': 'A', 'context': 'proposal'},
    {'cat': 'dialogue', 'text': 'Ah. Je vais réfléchir. Longtemps.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0124_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0124', 'turn': 4, 'speaker': 'B', 'context': 'proposal'},
    {'cat': 'dialogue', 'text': "Où étiez-vous quand le phare s'est éteint ?", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0125_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0125', 'turn': 1, 'speaker': 'A', 'context': 'alibi'},
    {'cat': 'dialogue', 'text': "Dans le jardin d'hiver. Avec mon chagrin.", 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0125_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0125', 'turn': 2, 'speaker': 'B', 'context': 'alibi'},
    {'cat': 'dialogue', 'text': 'Votre chagrin peut le confirmer ?', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0125_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0125', 'turn': 3, 'speaker': 'A', 'context': 'alibi'},
    {'cat': 'dialogue', 'text': 'Vous chantez des chansons tristes, mademoiselle ?', 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0126_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0126', 'turn': 1, 'speaker': 'A', 'context': 'gloomy'},
    {'cat': 'dialogue', 'text': 'Que des gaies ! Les tristes, je les garde pour le matin.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0126_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0126', 'turn': 2, 'speaker': 'B', 'context': 'gloomy'},
    {'cat': 'dialogue', 'text': "Moi, je n'ai que des matins.", 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0126_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0126', 'turn': 3, 'speaker': 'A', 'context': 'gloomy'},
    {'cat': 'dialogue', 'text': "Mon colonel, vous savez qu'on vous entend ronfler depuis la cuisine ?", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0127_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0127', 'turn': 1, 'speaker': 'A', 'context': 'snore'},
    {'cat': 'dialogue', 'text': 'Je ne ronfle pas, mademoiselle ! Je respire militairement.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0127_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0127', 'turn': 2, 'speaker': 'B', 'context': 'snore'},
    {'cat': 'dialogue', 'text': "Mademoiselle Rosalie, vous n'entrerez pas dans ma chambre avant le soir.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0128_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0128', 'turn': 1, 'speaker': 'A', 'context': 'room'},
    {'cat': 'dialogue', 'text': 'Même pas pour faire le lit, monsieur le comte ?', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0128_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0128', 'turn': 2, 'speaker': 'B', 'context': 'room'},
    {'cat': 'dialogue', 'text': 'Je ne dors pas dans un lit.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0128_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0128', 'turn': 3, 'speaker': 'A', 'context': 'room'},
    {'cat': 'dialogue', 'text': "Oh. Alors j'aurai moins de travail.", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0128_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0128', 'turn': 4, 'speaker': 'B', 'context': 'room'},
    {'cat': 'dialogue', 'text': 'Mademoiselle Sandra, vous savez pas la meilleure ?', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0129_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0129', 'turn': 1, 'speaker': 'A', 'context': 'gossip'},
    {'cat': 'dialogue', 'text': 'Dites, dites !', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0129_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0129', 'turn': 2, 'speaker': 'B', 'context': 'gossip'},
    {'cat': 'dialogue', 'text': 'Monsieur Victor a mis sa montre au clou à Paris.', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0129_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0129', 'turn': 3, 'speaker': 'A', 'context': 'gossip'},
    {'cat': 'dialogue', 'text': 'Ça, ma petite, tout le monde le sait. Trouvez mieux.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0129_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0129', 'turn': 4, 'speaker': 'B', 'context': 'gossip'},
    {'cat': 'dialogue', 'text': 'Rosalie, vous êtes ravissante ce soir.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0130_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0130', 'turn': 1, 'speaker': 'A', 'context': 'wink'},
    {'cat': 'dialogue', 'text': 'Oh, Monsieur Victor ! Vous dites ça à toutes les femmes de chambre.', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0130_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0130', 'turn': 2, 'speaker': 'B', 'context': 'wink'},
    {'cat': 'dialogue', 'text': 'Seulement aux plus discrètes.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0130_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0130', 'turn': 3, 'speaker': 'A', 'context': 'wink'},
    {'cat': 'dialogue', 'text': "Monsieur Minuit, y a quelqu'un qui marche au grenier la nuit.", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0131_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0131', 'turn': 1, 'speaker': 'A', 'context': 'footsteps'},
    {'cat': 'dialogue', 'text': 'Je sais.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0131_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0131', 'turn': 2, 'speaker': 'B', 'context': 'footsteps'},
    {'cat': 'dialogue', 'text': "Vous savez qui c'est ?", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0131_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0131', 'turn': 3, 'speaker': 'A', 'context': 'footsteps'},
    {'cat': 'dialogue', 'text': 'Oui. Ne montez pas.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0131_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0131', 'turn': 4, 'speaker': 'B', 'context': 'footsteps'},
    {'cat': 'dialogue', 'text': "T'es d'où, toi, avec cet accent ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0132_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0132', 'turn': 1, 'speaker': 'A', 'context': 'north'},
    {'cat': 'dialogue', 'text': 'De Roubaix, mademoiselle ! Et vous ?', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0132_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0132', 'turn': 2, 'speaker': 'B', 'context': 'north'},
    {'cat': 'dialogue', 'text': 'De la Butte, ma belle. On est du même côté du manche.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0132_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0132', 'turn': 3, 'speaker': 'A', 'context': 'north'},
    {'cat': 'dialogue', 'text': "Madame, votre chanson m'a fait monter les larmes aux yeux.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0133_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0133', 'turn': 1, 'speaker': 'A', 'context': 'blues'},
    {'cat': 'dialogue', 'text': "Mmm, c'est le blues, honey. Même les colonels y ont droit.", 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0133_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0133', 'turn': 2, 'speaker': 'B', 'context': 'blues'},
    {'cat': 'dialogue', 'text': "Vous avez l'air d'une très vieille âme, monsieur le comte.", 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0134_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0134', 'turn': 1, 'speaker': 'A', 'context': 'old soul'},
    {'cat': 'dialogue', 'text': "Vous n'imaginez pas à quel point, madame.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0134_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0134', 'turn': 2, 'speaker': 'B', 'context': 'old soul'},
    {'cat': 'dialogue', 'text': 'Mmm. Je vous chanterai une berceuse. Une ancienne.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0134_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0134', 'turn': 3, 'speaker': 'A', 'context': 'old soul'},
    {'cat': 'dialogue', 'text': 'Lou, comment fait-on pour chanter avec un cœur brisé ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0135_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0135', 'turn': 1, 'speaker': 'A', 'context': 'heartbreak'},
    {'cat': 'dialogue', 'text': 'On le recolle avec du bourbon, et on chante quand même, honey.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0135_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0135', 'turn': 2, 'speaker': 'B', 'context': 'heartbreak'},
    {'cat': 'dialogue', 'text': 'Toi, mon petit, tu as des yeux de joueur qui a tout perdu.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0136_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0136', 'turn': 1, 'speaker': 'A', 'context': 'broke'},
    {'cat': 'dialogue', 'text': "C'est écrit sur ma figure ?", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0136_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0136', 'turn': 2, 'speaker': 'B', 'context': 'broke'},
    {'cat': 'dialogue', 'text': 'Mmm. Le blues reconnaît les siens.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0136_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0136', 'turn': 3, 'speaker': 'A', 'context': 'broke'},
    {'cat': 'dialogue', 'text': 'Vous voyez tout depuis la scène, madame.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0137_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0137', 'turn': 1, 'speaker': 'A', 'context': 'watching'},
    {'cat': 'dialogue', 'text': 'Mmm. Je vois qui écoute et qui ment, honey.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0137_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0137', 'turn': 2, 'speaker': 'B', 'context': 'watching'},
    {'cat': 'dialogue', 'text': 'Alors nous faisons le même métier.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0137_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0137', 'turn': 3, 'speaker': 'A', 'context': 'watching'},
    {'cat': 'dialogue', 'text': 'Lou ! Tu me prêtes ta rose pour mon numéro ?', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0138_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0138', 'turn': 1, 'speaker': 'A', 'context': 'singers'},
    {'cat': 'dialogue', 'text': 'Mmm, prends-la, ma belle. Elle a vu plus de scènes que nous deux.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0138_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0138', 'turn': 2, 'speaker': 'B', 'context': 'singers'},
    {'cat': 'dialogue', 'text': 'Colonel, une petite question : quel régiment, à Verdun ?', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0139_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0139', 'turn': 1, 'speaker': 'A', 'context': 'verdun check'},
    {'cat': 'dialogue', 'text': 'Le... le régiment de cavalerie, mademoiselle !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0139_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0139', 'turn': 2, 'speaker': 'B', 'context': 'verdun check'},
    {'cat': 'dialogue', 'text': "Il n'y avait pas de cavalerie à Verdun.", 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0139_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0139', 'turn': 3, 'speaker': 'A', 'context': 'verdun check'},
    {'cat': 'dialogue', 'text': "Raison de plus pour qu'on s'en souvienne !", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0139_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0139', 'turn': 4, 'speaker': 'B', 'context': 'verdun check'},
    {'cat': 'dialogue', 'text': 'Comte, une interview pour Le Petit Parisien ?', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0140_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0140', 'turn': 1, 'speaker': 'A', 'context': 'interview'},
    {'cat': 'dialogue', 'text': 'Avec plaisir, mademoiselle. À minuit, dans la crypte.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0140_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0140', 'turn': 2, 'speaker': 'B', 'context': 'interview'},
    {'cat': 'dialogue', 'text': 'Euh... au salon, plutôt ?', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0140_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0140', 'turn': 3, 'speaker': 'A', 'context': 'interview'},
    {'cat': 'dialogue', 'text': "Vous écrivez la chronique mondaine ? Écrivez que j'étais la plus belle.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0141_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0141', 'turn': 1, 'speaker': 'A', 'context': 'column'},
    {'cat': 'dialogue', 'text': "J'écris la vérité, mademoiselle.", 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0141_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0141', 'turn': 2, 'speaker': 'B', 'context': 'column'},
    {'cat': 'dialogue', 'text': "C'est la même chose.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0141_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0141', 'turn': 3, 'speaker': 'A', 'context': 'column'},
    {'cat': 'dialogue', 'text': 'Monsieur Victor, combien devez-vous exactement à Tony les Gants ?', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0142_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0142', 'turn': 1, 'speaker': 'A', 'context': 'debts'},
    {'cat': 'dialogue', 'text': 'Qui vous a dit ça ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0142_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0142', 'turn': 2, 'speaker': 'B', 'context': 'debts'},
    {'cat': 'dialogue', 'text': 'Tony. Il a donné le chiffre. Il était même fier.', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0142_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0142', 'turn': 3, 'speaker': 'A', 'context': 'debts'},
    {'cat': 'dialogue', 'text': 'Vous posez trop de questions, mademoiselle.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0143_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0143', 'turn': 1, 'speaker': 'A', 'context': 'rivals'},
    {'cat': 'dialogue', 'text': "Et vous, vous n'en posez aucune. Vous savez déjà les réponses ?", 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0143_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0143', 'turn': 2, 'speaker': 'B', 'context': 'rivals'},
    {'cat': 'dialogue', 'text': 'Certaines.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0143_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0143', 'turn': 3, 'speaker': 'A', 'context': 'rivals'},
    {'cat': 'dialogue', 'text': 'Odette, une déclaration pour la presse ?', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0144_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0144', 'turn': 1, 'speaker': 'A', 'context': 'scoop'},
    {'cat': 'dialogue', 'text': "Écris que j'ai la plus belle voix de Paris, et que je suis libre samedi.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0144_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0144', 'turn': 2, 'speaker': 'B', 'context': 'scoop'},
    {'cat': 'dialogue', 'text': 'Je note. Surtout le samedi.', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0144_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0144', 'turn': 3, 'speaker': 'A', 'context': 'scoop'},
    {'cat': 'dialogue', 'text': 'Colonel, avez-vous déjà visité la Chine ?', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0145_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0145', 'turn': 1, 'speaker': 'A', 'context': 'china'},
    {'cat': 'dialogue', 'text': 'Jamais, mademoiselle. Trop loin pour un cheval.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0145_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0145', 'turn': 2, 'speaker': 'B', 'context': 'china'},
    {'cat': 'dialogue', 'text': "C'est dommage. Les chevaux y sont très patients.", 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0145_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0145', 'turn': 3, 'speaker': 'A', 'context': 'china'},
    {'cat': 'dialogue', 'text': 'Mademoiselle Mei, du thé ?', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0146_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0146', 'turn': 1, 'speaker': 'A', 'context': 'tea'},
    {'cat': 'dialogue', 'text': 'Volontiers, comte. Mais vous ne buvez rien, vous.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0146_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0146', 'turn': 2, 'speaker': 'B', 'context': 'tea'},
    {'cat': 'dialogue', 'text': 'Je bois autre chose. Plus tard.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0146_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0146', 'turn': 3, 'speaker': 'A', 'context': 'tea'},
    {'cat': 'dialogue', 'text': 'Je vois. Je ne vous tournerai pas le dos.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0146_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0146', 'turn': 4, 'speaker': 'B', 'context': 'tea'},
    {'cat': 'dialogue', 'text': 'Votre émeraude est magnifique, mademoiselle Sandra.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0147_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0147', 'turn': 1, 'speaker': 'A', 'context': 'jade'},
    {'cat': 'dialogue', 'text': 'Et votre jade, ma chère ! On échange ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0147_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0147', 'turn': 2, 'speaker': 'B', 'context': 'jade'},
    {'cat': 'dialogue', 'text': 'Le jade ne se donne pas. Il se gagne.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0147_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0147', 'turn': 3, 'speaker': 'A', 'context': 'jade'},
    {'cat': 'dialogue', 'text': 'Mademoiselle Mei, vous jouez au mah-jong ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0148_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0148', 'turn': 1, 'speaker': 'A', 'context': 'mahjong'},
    {'cat': 'dialogue', 'text': "Depuis l'âge de six ans, monsieur Victor.", 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0148_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0148', 'turn': 2, 'speaker': 'B', 'context': 'mahjong'},
    {'cat': 'dialogue', 'text': 'Ah. Alors je vais plutôt vous inviter à danser.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0148_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0148', 'turn': 3, 'speaker': 'A', 'context': 'mahjong'},
    {'cat': 'dialogue', 'text': 'Vous ne buvez jamais, monsieur Minuit.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0149_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0149', 'turn': 1, 'speaker': 'A', 'context': 'silence'},
    {'cat': 'dialogue', 'text': "Vous l'avez remarqué.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0149_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0149', 'turn': 2, 'speaker': 'B', 'context': 'silence'},
    {'cat': 'dialogue', 'text': "Je remarque tout. C'est pour cela que je vous parle.", 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0149_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0149', 'turn': 3, 'speaker': 'A', 'context': 'silence'},
    {'cat': 'dialogue', 'text': "C'est vrai qu'à Shanghai, il y a des cabarets plus grands que l'Opéra ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0150_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0150', 'turn': 1, 'speaker': 'A', 'context': 'shanghai'},
    {'cat': 'dialogue', 'text': 'Plus grands, oui. Plus gais, non. Vous y feriez sensation.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0150_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0150', 'turn': 2, 'speaker': 'B', 'context': 'shanghai'},
    {'cat': 'dialogue', 'text': 'Tu me trouves un contrat, je prends le bateau demain !', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0150_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0150', 'turn': 3, 'speaker': 'A', 'context': 'shanghai'},
]
